<div class="grid gap-5 md:grid-cols-2"><div><label class="label" for="title">Title</label><input class="input" id="title" name="title" value="{{ old('title',$task->title ?? '') }}" required maxlength="150"></div><div><label class="label" for="due_date">Due date</label><input class="input" type="date" id="due_date" name="due_date" value="{{ old('due_date',isset($task) ? $task->due_date->format('Y-m-d') : '') }}" required></div><div><label class="label" for="priority">Priority</label><select class="input" id="priority" name="priority" required>@foreach(['low','medium','high'] as $value)<option value="{{ $value }}" @selected(old('priority',$task->priority ?? 'medium')===$value)>{{ ucfirst($value) }}</option>@endforeach</select></div><div><label class="label" for="status">Status</label><select class="input" id="status" name="status" required>@foreach(['pending','in_progress','done'] as $value)<option value="{{ $value }}" @selected(old('status',$task->status ?? 'pending')===$value)>{{ ucfirst(str_replace('_',' ',$value)) }}</option>@endforeach</select></div><div class="md:col-span-2"><label class="label" for="description">Description</label><textarea class="input" id="description" name="description" rows="5" maxlength="2000">{{ old('description',$task->description ?? '') }}</textarea></div></div><div class="mt-6 flex gap-2"><button class="btn btn-primary">{{ $buttonText }}</button><a class="btn btn-secondary" href="{{ route('tasks.index') }}">Cancel</a></div>
